document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();modal('문의·문서 검색',`<div class="search-field"><input id="global-query" data-input="global-search" aria-label="전체 검색" placeholder="검색어를 입력하세요"></div><div class="global-results" id="global-results">${globalResults('')}</div>`,'',true);}if(e.key==='Tab'&&$('.modal')){const nodes=[...$('.modal').querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')],first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(['Enter',' '].includes(e.key)&&e.target.matches('tr[data-action="thread"]')){e.preventDefault();openThread(e.target.dataset.id);}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(names[page]){state.page=page;state.mobileChat=false;renderShell();}});
const initial=location.hash.slice(1);if(names[initial])state.page=initial;
